package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import jakarta.servlet.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import java.util.UUID;
@RestController @org.springframework.boot.autoconfigure.condition.ConditionalOnExpression("${medical.formal-agent-acceptance.enabled:false} and ${medical.expert-qualification.enabled:false}")
public final class FormalAgentAcceptanceController {
 private final ApplicationSessionIdentity identities;private final FormalAgentAcceptanceService decisions;private final FormalEvaluationScoreBindingService bindings;private final FormalEvaluationScoreBindingSchema schema;private final PermissionSchema json;
 public FormalAgentAcceptanceController(ApplicationSessionIdentity identities,FormalAgentAcceptanceService decisions,FormalEvaluationScoreBindingService bindings,FormalEvaluationScoreBindingSchema schema,PermissionSchema json){this.identities=identities;this.decisions=decisions;this.bindings=bindings;this.schema=schema;this.json=json;}
 @PostMapping(value="/api/formal-agent-acceptance-decisions",consumes="application/json") public JsonNode decide(HttpServletRequest q,HttpServletResponse r,Authentication auth)throws Exception{String context=FormalAgentPublicationController.headers(q);return response(r,decisions.decide(identities.requireCurrent(q,auth),context,FormalAgentPublicationController.key(q),FormalAgentPublicationController.body(q)));}
 @GetMapping("/api/formal-agent-acceptance-records/{recordId}") public JsonNode read(HttpServletRequest q,HttpServletResponse r,Authentication auth,@PathVariable("recordId") String recordId)throws Exception{String context=FormalAgentPublicationController.headers(q);FormalAgentPublicationController.noBody(q);return response(r,decisions.read(identities.requireCurrent(q,auth),context,recordId));}
 @GetMapping("/api/formal-agent-acceptance-records/{recordId}/operation-receipts/{operationId}") public JsonNode receipt(HttpServletRequest q,HttpServletResponse r,Authentication auth,@PathVariable("recordId") String recordId,@PathVariable("operationId") String operationId)throws Exception{String context=FormalAgentPublicationController.headers(q);FormalAgentPublicationController.noBody(q);return response(r,decisions.receipt(identities.requireCurrent(q,auth),context,recordId,operationId));}
 @PostMapping(value="/api/formal-evaluation-score-bindings",consumes="application/json") public JsonNode bind(HttpServletRequest q,HttpServletResponse r,Authentication auth)throws Exception{String context=FormalAgentPublicationController.headers(q);return response(r,bindings.bind(identities.requireCurrent(q,auth),context,FormalAgentPublicationController.key(q),FormalAgentPublicationController.body(q)));}
 @PostMapping(value="/api/formal-evaluation-score-bindings/recovery",consumes="application/json") public JsonNode recover(HttpServletRequest q,HttpServletResponse r,Authentication auth)throws Exception{String context=FormalAgentPublicationController.headers(q);if(q.getHeader("Idempotency-Key")!=null)throw new SchemaRejection(ErrorCode.SCHEMA_INVALID);int max=2*FormalAgentPublicationSchema.MAXIMUM_BYTES;if(q.getContentLengthLong()>max)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);byte[] bytes=q.getInputStream().readNBytes(max+1);if(bytes.length>max)throw new TenantAccessException(ErrorCode.FILE_TOO_LARGE);var request=schema.recovery(bytes);return response(r,bindings.recover(identities.requireCurrent(q,auth),context,request.required("original_key").asText(),request.required("request")));}
 private JsonNode response(HttpServletResponse r,JsonNode data){String id=UUID.randomUUID().toString();r.setHeader("Cache-Control","no-store");r.setHeader("X-Schema-Version","1.0.0");r.setHeader("X-Request-Id",id);return json.tree(new InterfaceProtocol.Envelope("1.0.0",id,"1",data));}

 @ExceptionHandler(SchemaRejection.class) void invalid(SchemaRejection e,HttpServletResponse r)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(r,422,e.code());}
 @ExceptionHandler(TenantAccessException.class) void denied(TenantAccessException e,HttpServletResponse r)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(r,e.code()==ErrorCode.DEPENDENCY_UNAVAILABLE?503:SimulationRuleVersionController.errorStatus(e.code()),e.code());}
 @ExceptionHandler(com.fasterxml.jackson.core.JsonProcessingException.class) void malformed(HttpServletResponse r)throws java.io.IOException{new com.ruoyi.medical.identity.IdentityErrorResponseWriter().write(r,422,ErrorCode.SCHEMA_INVALID);}
}
